<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { Plus, Search, SlidersHorizontal, PanelRightClose, PanelRightOpen } from 'lucide-vue-next'
import PageHeader from '../components/PageHeader.vue'
import TaskRow from '../components/TaskRow.vue'
import TaskActionsMenu from '../components/TaskActionsMenu.vue'
import EmptyState from '../components/EmptyState.vue'
import AppDialog from '../components/AppDialog.vue'
import TaskEditor from '../components/TaskEditor.vue'
import { useTasksStore } from '../stores/tasks'
import { useResourcesStore } from '../stores/resources'
import { useAppStore } from '../stores/app'
import type { Task, TaskCategory, TaskStatus } from '../types/api'

const store = useTasksStore(); const resources = useResourcesStore(); const app = useAppStore()
const view = ref('open'); const query = ref(''); const category = ref<TaskCategory | ''>(''); const course = ref(''); const source = ref(''); const statusFilter = ref<TaskStatus | ''>(''); const deadlineFrom = ref(''); const deadlineTo = ref(''); const showFilters = ref(false); const editorOpen = ref(false); const editing = ref<Task | null>(null); const deleteTarget = ref<Task | null>(null); const asideCollapsed = ref(false)
const categories: Array<{ value: TaskCategory; label: string }> = [{ value:'homework', label:'作业' }, { value:'exam', label:'考试' }, { value:'competition', label:'比赛' }, { value:'activity', label:'活动' }, { value:'notice', label:'通知' }, { value:'other', label:'其他' }]
const visible = computed(() => store.items)
const activeFilterCount = computed(() => [category.value, course.value, source.value, statusFilter.value, deadlineFrom.value, deadlineTo.value].filter(Boolean).length)
const overview = computed(() => { const open = store.items.filter(task => task.status === 'pending' || task.status === 'pending_confirm'); const weekEnd = Date.now() + 7 * 86_400_000; const next = [...open].filter(task => task.deadline).sort((a,b) => (a.deadline || '').localeCompare(b.deadline || ''))[0]; return { week: open.filter(task => task.deadline && new Date(task.deadline).getTime() <= weekEnd).length, confirm: open.filter(task => task.status === 'pending_confirm').length, next } })
function queryString() { const params = new URLSearchParams(); if (statusFilter.value) params.set('status', statusFilter.value); else if (view.value === 'done') params.set('status', 'done'); else if (['today','week','later'].includes(view.value)) { params.set('status', 'pending'); const now = new Date(); const start = new Date(now); start.setHours(0,0,0,0); const end = new Date(start); if (view.value === 'today') end.setDate(end.getDate() + 1); else if (view.value === 'week') end.setDate(end.getDate() + 7); else { start.setDate(start.getDate() + 7); end.setFullYear(end.getFullYear() + 1) } params.set('deadline_from', start.toISOString()); params.set('deadline_to', end.toISOString()) } else if (view.value === 'open') params.set('status', 'pending'); if (category.value) params.set('category', category.value); if (course.value) params.set('course', course.value); if (source.value) params.set('source_id', source.value); if (deadlineFrom.value) params.set('deadline_from', new Date(deadlineFrom.value).toISOString()); if (deadlineTo.value) params.set('deadline_to', new Date(`${deadlineTo.value}T23:59:59`).toISOString()); if (query.value.trim()) params.set('q', query.value.trim()); params.set('limit', '200'); return params.toString() }
async function load() { await store.load(queryString()) }
onMounted(async () => { asideCollapsed.value = localStorage.getItem('campuscue-tasks-aside-collapsed') === '1'; await Promise.all([load(), resources.loadSources()]) })
watch([view, category, course, source, statusFilter, deadlineFrom, deadlineTo, query], () => { void load() })
function toggleAside() { asideCollapsed.value = !asideCollapsed.value; localStorage.setItem('campuscue-tasks-aside-collapsed', asideCollapsed.value ? '1' : '0') }
function clearFilters() { category.value = ''; course.value = ''; source.value = ''; statusFilter.value = ''; deadlineFrom.value = ''; deadlineTo.value = '' }
function openCreate() { editing.value = null; editorOpen.value = true }; function openEdit(task: Task) { editing.value = task; editorOpen.value = true }
function saved(task: Task) { editorOpen.value = false; const index = store.items.findIndex(item => item.id === task.id); if (index >= 0) store.items[index] = task; else store.items.unshift(task); app.toast(editing.value ? '任务已更新' : '任务已添加') }
async function action(id: number, actionName: 'complete'|'dismiss') { try { await store.mutate(id, actionName); app.toast(actionName === 'complete' ? '任务已完成' : '任务已忽略') } catch { app.toast('保存失败，已恢复原状态') } }
async function remove() { if (!deleteTarget.value) return; try { await store.remove(deleteTarget.value.id); app.toast('任务已删除'); deleteTarget.value = null } catch { app.toast('删除失败，任务已恢复') } }
</script>
<template><section class="page-content tasks-page"><PageHeader eyebrow="任务中心" title="任务" description="把校园里的截止事项整理成清晰的下一步。"><button class="button button-primary" @click="openCreate"><Plus :size="16" />新建任务</button></PageHeader><div class="toolbar task-toolbar"><div class="segmented"><button v-for="item in [{id:'today',label:'今天'},{id:'week',label:'本周'},{id:'later',label:'以后'},{id:'done',label:'已完成'},{id:'open',label:'进行中'}]" :key="item.id" :class="{ active: view === item.id }" @click="view = item.id">{{ item.label }}</button></div><label class="search-box"><Search :size="16" /><input v-model="query" aria-label="搜索任务" placeholder="搜索任务或课程" /></label><button class="button button-secondary filter-button" :class="{ 'has-filters': activeFilterCount }" :aria-expanded="showFilters" aria-label="筛选" @click="showFilters = true"><SlidersHorizontal :size="17" /><span>筛选<span v-if="activeFilterCount"> · {{ activeFilterCount }}</span></span></button><button class="icon-button aside-toggle" :aria-label="asideCollapsed ? '显示任务概览' : '收起任务概览'" :aria-expanded="!asideCollapsed" @click="toggleAside"><PanelRightOpen v-if="asideCollapsed" :size="17" /><PanelRightClose v-else :size="17" /></button></div><div class="task-page-layout"><section class="task-list-panel"><div class="list-heading"><strong>{{ store.total }} 个任务</strong><span v-if="store.loading" class="loading-label">正在同步…</span></div><div v-if="visible.length" class="task-list"><div v-for="task in visible" :key="task.id" class="task-with-actions"><TaskRow :task="task" :show-dismiss="false" @complete="action(task.id, 'complete')" /><TaskActionsMenu :task="task" @dismiss="action(task.id, 'dismiss')" @edit="openEdit(task)" @remove="deleteTarget = task" /></div></div><EmptyState v-else variant="task" title="没有匹配的任务" description="调整筛选条件，或创建一个新的校园事务。"><button class="text-link button-reset" @click="clearFilters">清除筛选</button><button class="text-link button-reset" @click="openCreate">新建任务</button></EmptyState></section><aside v-if="!asideCollapsed" class="panel task-aside"><div class="overview-heading"><div><p class="section-kicker">任务概览</p><h3>把下一步放在眼前</h3></div><span class="cue-mark" aria-hidden="true"><i></i><b></b></span></div><div class="overview-stats"><div><strong>{{ overview.week }}</strong><span>本周截止</span></div><div><strong>{{ overview.confirm }}</strong><span>待确认</span></div><div><strong>{{ overview.next ? '1' : '0' }}</strong><span>最近截止</span></div></div><p v-if="overview.next" class="muted-copy next-deadline">最近是「{{ overview.next.title }}」<br />{{ overview.next.deadline }}</p><p v-else class="muted-copy">暂时没有带截止时间的待办。</p></aside></div><AppDialog :open="showFilters" title="筛选任务" description="把不常用的条件收进这里。" variant="sheet" @close="showFilters = false"><form class="filters" @submit.prevent="showFilters = false"><label>类型<select v-model="category"><option value="">全部类型</option><option v-for="item in categories" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label>状态<select v-model="statusFilter"><option value="">跟随当前视图</option><option value="pending">进行中</option><option value="pending_confirm">待确认</option><option value="done">已完成</option></select></label><label>课程<input v-model="course" placeholder="按课程筛选" /></label><label>来源<select v-model="source"><option value="">全部来源</option><option v-for="item in resources.sources" :key="item.id" :value="String(item.id)">{{ item.name || item.conversation_id }}</option></select></label><label>从<input v-model="deadlineFrom" type="date" /></label><label>到<input v-model="deadlineTo" type="date" /></label><div class="filter-actions"><button type="button" class="button button-secondary" @click="clearFilters">清除筛选</button><button class="button button-primary">应用筛选</button></div></form></AppDialog><AppDialog :open="editorOpen" :title="editing ? '编辑任务' : '新建任务'" description="填写后即可加入你的任务清单。" @close="editorOpen = false"><TaskEditor :task="editing" :sources="resources.sources" @saved="saved" @close="editorOpen = false" /></AppDialog><AppDialog :open="Boolean(deleteTarget)" title="删除任务" description="删除后任务不会出现在任务列表中。" @close="deleteTarget = null"><p class="dialog-copy">确定删除“{{ deleteTarget?.title }}”吗？这个操作不能撤销。</p><template #footer><button class="button button-secondary" @click="deleteTarget = null">取消</button><button class="button button-danger" @click="remove">删除任务</button></template></AppDialog></section></template>
